using sv_628c7b16b59543cd9b8f68cf0457d43a.Models;

namespace sv_628c7b16b59543cd9b8f68cf0457d43a.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Pasta Carbonara", "Rich Roman pasta with guanciale, egg yolk, Pecorino Romano, and black pepper.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa powder.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Sushi Rolls", "Fresh salmon and avocado maki rolls with seasoned rice and nori.", 60),
            new(5, "Ramen", "Tonkotsu broth with chashu pork, soft-boiled egg, and hand-pulled noodles.", 40),
            new(6, "Tempura", "Lightly battered and fried shrimp and vegetables served with dipping sauce.", 20),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork with pineapple, cilantro, and onion on corn tortillas.", 35),
            new(8, "Guacamole", "Fresh avocado mashed with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Churros", "Fried dough sticks coated in cinnamon sugar with chocolate dipping sauce.", 25),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_628c7b16b59543cd9b8f68cf0457d43a.Models
@using sv_628c7b16b59543cd9b8f68cf0457d43a.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes for Cuisine @CuisineId</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <div class="recipe-list">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="card mb-3">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text">@recipe.Description</p>
                    <span class="badge bg-secondary">Prep: @recipe.PrepTimeMinutes min</span>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;

    private CancellationTokenSource? _loadCts;
    private int _lastLoadedCuisineId;

    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    protected override async Task OnParametersSetAsync()
    {
        // Only reload if the cuisine changed; sort changes are display-only.
        if (CuisineId == _lastLoadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingLoadAsync();

        _loadCts = new CancellationTokenSource();
        var token = _loadCts.Token;

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        if (!_isRefreshing)
        {
            StateHasChanged();
        }

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, token);

            // Don't apply results if this load was cancelled.
            if (token.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
            _lastLoadedCuisineId = CuisineId;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Expected when navigating away or changing cuisine; do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return new List<Recipe>();
        }

        return Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes,
        };
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

